import { expect, test, uniqueName } from "../../fixtures";
import type { APIRequestContext } from "@playwright/test";

const W9 = "Legal Name: Acme Freight LLC\nTax ID: 12-3456789\nBusiness Type: LLC\n";
const CONTRACT = "Counterparty: Acme Freight LLC\nEffective Date: 2026-01-01\nExpiry Date: 2027-12-31\n";

function isoDaysFromToday(days: number): string {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

function insuranceText(expiry: string): string {
  return `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;
}

async function upload(member: APIRequestContext, vendorId: string, kind: string, text: string) {
  const res = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: { name: `${kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(text) },
    },
  });
  expect(res.status(), await res.text()).toBe(201);
  return (await res.json()) as { id: string };
}

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Expired Cert"), category: "logistics", contact_email: "ops@acme.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };

  const insurance = await upload(member, vendor.id, "insurance_certificate", insuranceText(isoDaysFromToday(-1)));
  await upload(member, vendor.id, "w9", W9);
  await upload(member, vendor.id, "contract", CONTRACT);

  // Wait for background extraction of all three documents.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/documents`);
        const docs = (await res.json()) as { status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 30_000 },
    )
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);

  const extractionRes = await member.get(`/api/documents/${insurance.id}/extraction`);
  expect(extractionRes.status(), await extractionRes.text()).toBe(200);
  const extraction = (await extractionRes.json()) as { id: string };

  // Act
  const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  expect(response.status(), await response.text()).toBe(409);
  const body = (await response.json()) as { error: { code: string } };
  expect(body.error.code, await response.text()).toBe("insurance_expired");
});
